<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ReadOnlyDocument from '../components/ReadOnlyDocument.vue'
import { getSubmissions, getSubmission, getProgress, stateLabel, decisionLabel, type Version, type Snapshot, type Progress } from '../api/manuscripts'
const route = useRoute(), router = useRouter(), versions = ref<Version[]>([]), selected = ref(''), snapshot = ref<Snapshot>(), progress = ref<Progress>(), status = ref(''), loading = ref(false), error = ref('')
let timer: ReturnType<typeof setTimeout> | undefined, active = true, selection = 0
function stop() { if (timer) clearTimeout(timer) }
async function refreshProgress(batch: string, current: number) { try { const result = await getProgress(batch); if (!active || current !== selection) return; progress.value = result; if (['QUEUED','RUNNING','WAITING_SERVICE'].includes(result.status)) timer = setTimeout(() => refreshProgress(batch, current), 3000) } catch (failure) { if (active && current === selection) error.value = failure instanceof Error ? failure.message : '进度读取失败' } }
async function select() { stop(); const current = ++selection; progress.value = undefined; snapshot.value = undefined; loading.value = true; error.value = ''; try { if (route.query.submission !== selected.value) await router.replace({ query: { ...route.query, submission: selected.value } }); const result = await getSubmission(selected.value); if (!active || current !== selection) return; snapshot.value = result; const version = versions.value.find(item => item.submissionId === selected.value); if (version?.batchId) await refreshProgress(version.batchId, current) } catch (failure) { if (current === selection) error.value = failure instanceof Error ? failure.message : '版本读取失败' } finally { if (current === selection) loading.value = false } }
async function load() { try { const result = await getSubmissions(String(route.params.id)); versions.value = result.items; status.value = result.status; selected.value = result.items.find(item => item.submissionId === route.query.submission)?.submissionId ?? result.items[0]?.submissionId ?? ''; if (selected.value) await select() } catch (failure) { error.value = failure instanceof Error ? failure.message : '历史读取失败' } }
onMounted(load); onBeforeUnmount(() => { active = false; stop() })
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="panel history-controls"><RouterLink to="/manuscripts">返回组织稿件</RouterLink><el-select v-model="selected" aria-label="送审版本" @change="select"><el-option v-for="version in versions" :key="version.submissionId" :value="version.submissionId" :label="`第${version.versionNo}版 · ${new Date(version.submittedAt).toLocaleString('zh-CN')}`" /></el-select><el-tag>{{ stateLabel[status] }}</el-tag><RouterLink v-if="status === 'RETURNED'" :to="`/manuscripts/${route.params.id}/edit`">修改并重新送审</RouterLink></div><div v-loading="loading"><template v-if="snapshot"><section class="panel"><p>第{{ snapshot.versionNo }}版 · 送审于{{ new Date(snapshot.submittedAt).toLocaleString('zh-CN') }}</p><el-alert v-if="snapshot.decision" :title="`人工决定：${decisionLabel[snapshot.decision.decision]}`" :description="snapshot.decision.reason || undefined" :closable="false" /><p v-else class="muted">等待人工审核</p><div v-if="progress" class="progress-summary"><strong>检测{{ stateLabel[progress.status] || progress.status }}</strong><span>{{ progress.completedItems }}/{{ progress.totalItems }} 项结束</span><span v-for="item in progress.items" :key="item.itemId">{{ item.type === 'TEXT' ? '正文' : item.type === 'IMAGE' ? '图片' : 'OCR文字' }}：{{ stateLabel[item.status] || item.status }}</span></div></section><section class="panel"><ReadOnlyDocument :document="snapshot" /></section></template><el-empty v-else-if="!loading && !error" description="暂无送审版本" /></div></template>
